// Local document extraction and cited passage retrieval. No remote model call.
function documentTerms(value){const cleaned=value.toLowerCase().replace(/请问|一下|这个|产品|说明书|是什么|怎么|如何|可以|是否|支持|多少|多久|我想|告诉我|有没有|能不能/g,' ');return [...new Set([...(cleaned.match(/[a-z0-9]{2,}/g)||[]),...(cleaned.match(/[\u4e00-\u9fff]{2,}/g)||[]).flatMap(s=>Array.from({length:s.length-1},(_,i)=>s.slice(i,i+2)))])]}
function findDocumentPassages(text,question){const terms=documentTerms(question);const parts=text.split(/\n\s*\n/).flatMap(p=>p.length>700?(p.match(/[\s\S]{1,500}/g)||[]):[p]).map(s=>s.trim()).filter(Boolean);return parts.map((p,i)=>({text:p,index:i+1,score:terms.reduce((sum,t)=>sum+(p.toLowerCase().includes(t)?t.length:0),0)})).filter(p=>p.score>0).sort((a,b)=>b.score-a.score).slice(0,2)}
function documentChatRuntime(data){
 const log=document.querySelector('#chat-log'),form=document.querySelector('#chat-form'),input=document.querySelector('#chat-question');
 function append(text,kind){const el=document.createElement('div');el.className='message '+kind;el.textContent=text;log.append(el);while(log.children.length>22)log.firstElementChild.remove();log.scrollTop=log.scrollHeight}
 function ask(question){question=question.trim().slice(0,240);if(!question)return;append(question,'user');const hits=findDocumentPassages(data.text,question);if(!hits.length){append('文档中未找到匹配内容。可以换用原文里的关键词，或打开原文查看。当前为本地关键词检索，不会补写文档未提供的信息。','assistant');return}append('找到以下相关原文：\n\n'+hits.map(h=>h.text+'\n〔'+data.name+' · 段落 '+h.index+'〕').join('\n\n'),'assistant')}
 function send(){ask(input.value);input.value=''}form.onsubmit=e=>{e.preventDefault();send()};form.querySelector('button').onclick=e=>{e.preventDefault();send()};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();send()}};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));document.querySelector('#source-text').textContent=data.text;document.querySelector('#source-name').textContent=data.name;append('你好，可以问我这份文档里的内容。回答会显示原文和出处。','assistant');
}
function documentSliceHtml(doc){const json=JSON.stringify(doc).replace(/</g,'\\u003c');const suggestions=doc.sample?['怎么调亮度？','可以无线使用吗？','保修多久？']:['主要功能有哪些？','如何使用？','注意事项有哪些？'];return `<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}html,body{height:100%;margin:0}body{font:14px system-ui;color:#243a43;background:#f1f6f7;display:flex;flex-direction:column}.top{padding:14px 16px 8px;border-bottom:1px solid #dce7e8}.top small{font-size:10px;color:#758c90;letter-spacing:1px}.top h2{font-size:18px;margin:4px 0}.top p{font-size:11px;margin:3px 0;color:#819498}#chat-log{flex:1;min-height:50px;overflow:auto;padding:12px 15px;display:flex;flex-direction:column;gap:9px}.message{padding:10px 12px;background:white;border-radius:10px;white-space:pre-wrap;line-height:1.7;font-size:12px;overflow-wrap:anywhere}.user{align-self:flex-end;background:#d5e9d8;max-width:90%}.assistant{align-self:flex-start}.quick{display:flex;gap:5px;padding:5px 12px;overflow-x:auto;flex-shrink:0}button{font:inherit;cursor:pointer}.quick button{white-space:nowrap;font-size:11px;border:1px solid #d7e2df;background:white;border-radius:20px;padding:7px 9px}form{display:flex;gap:6px;padding:8px 12px 10px}input{min-width:0;flex:1;padding:10px;border:1px solid #cddbd8;border-radius:7px;font:inherit;font-size:12px}form button{background:#2b4f49;color:white;border:0;padding:9px 13px;border-radius:7px}details{padding:0 14px 8px;font-size:10px;max-height:110px;overflow:auto}summary{cursor:pointer;color:#718580}pre{white-space:pre-wrap;font:12px system-ui}button:focus-visible,input:focus-visible{outline:2px solid #698c68;outline-offset:2px}</style><body><div class="top"><small>DOCUMENT → CONVERSATIONAL SLICE</small><h2>${escapeHtml(doc.title||doc.name)}</h2><p>本地原文检索 · 非 AI 推理 · 不联网</p></div><div id="chat-log" role="log" aria-live="polite" aria-label="文档问答记录"></div><div class="quick">${suggestions.map(q=>`<button type="button" data-question="${escapeHtml(q)}">${escapeHtml(q)}</button>`).join('')}</div><form id="chat-form"><input id="chat-question" aria-label="向文档提问" placeholder="问问这份说明书…" required maxlength="240"><button>发送</button></form><details><summary>查看原文 · <span id="source-name"></span></summary><pre id="source-text"></pre></details><script>${documentTerms.toString()};${findDocumentPassages.toString()};(${documentChatRuntime.toString()})(${json});<\/script></body></html>`}
let uploadedDocument=null,documentReadId=0,mammothLoad=null;
function loadMammoth(){if(window.mammoth)return Promise.resolve(window.mammoth);if(!mammothLoad)mammothLoad=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/mammoth.browser.js';s.onload=()=>resolve(window.mammoth);s.onerror=()=>{mammothLoad=null;reject(Error('Word 读取组件加载失败，请重试。'))};document.head.append(s)});return mammothLoad}
async function extractDocument(file){const ext=file.name.split('.').pop().toLowerCase();if(!file.size||file.size>8*1024*1024)throw Error('文档不能为空，且不能超过 8 MB。');let text='',limitNote='';if(ext==='txt'||ext==='md'){text=await file.text()}else if(ext==='docx'){const m=await loadMammoth();const result=await m.extractRawText({arrayBuffer:await file.arrayBuffer()});text=result.value}else if(ext==='pdf'){const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('vendor/pdf.worker.mjs',location.href).href;const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true});const pdf=await task.promise;try{if(pdf.numPages>60)limitNote='仅读取前 60 页。';const pages=[];for(let i=1;i<=Math.min(pdf.numPages,60);i++){const page=await pdf.getPage(i);const content=await page.getTextContent();const line=content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('');if(line.trim())pages.push('第 '+i+' 页\n'+line);page.cleanup()}text=pages.join('\n\n')}finally{await pdf.destroy()}}else{throw Error('支持 Word .docx、TXT、Markdown 和文字版 PDF；旧版 .doc 请先另存为 .docx。')}text=text.replace(/\r\n/g,'\n').trim();if(text.length<10)throw Error('没有读到可用文字。扫描版 PDF 或图片文档需要先进行 OCR 文字识别。');if(text.includes('\uFFFD')&&text.match(/\uFFFD/g).length>10)throw Error('文本编码无法识别，请另存为 UTF-8 TXT。');if(text.length>60000){text=text.slice(0,60000);limitNote+='仅保留前 60,000 个字符。'}return {name:file.name,title:file.name.replace(/\.[^.]+$/,''),text,limitNote}}
const documentInfo=document.createElement('div');documentInfo.id='document-upload-info';documentInfo.hidden=true;documentInfo.innerHTML='<strong id="document-name"></strong><small id="document-detail"></small><button type="button" id="remove-document">移除文档</button>';document.querySelector('#file-info').after(documentInfo);
function refreshDocumentInfo(){documentInfo.hidden=!uploadedDocument;document.querySelector('#document-name').textContent=uploadedDocument?'▤ '+uploadedDocument.name:'';document.querySelector('#document-detail').textContent=uploadedDocument?uploadedDocument.text.length.toLocaleString()+' 字符已读取 · 将生成可提问的 Slice。'+(uploadedDocument.limitNote||''):''}
const docModeBefore=setCreationMode;setCreationMode=function(mode,clear=true){if(clear){uploadedDocument=null;documentReadId++;refreshDocumentInfo()}docModeBefore(mode,clear);if(creationMode==='image'){document.querySelector('#work-file').accept='.docx,.txt,.md,.pdf,image/png,image/jpeg,image/webp';drop.querySelector('strong').textContent='上传文档或图片（可选）';document.querySelector('#upload-hint').textContent='Word .docx / TXT / PDF / 图片 · 文档最大 8 MB';document.querySelector('.generation-note').textContent='文档生成可对话 Slice，回答引用原文。当前为本地检索，不调用 AI；扫描 PDF 需先识别文字。'}documentInfo.hidden=creationMode!=='image'||!uploadedDocument};
const docImportBefore=importFile;importFile=async function(file){if(creationMode!=='image'||!file)return docImportBefore(file);const ext=file.name.split('.').pop().toLowerCase();if(!['docx','doc','txt','md','pdf'].includes(ext)){uploadedDocument=null;documentReadId++;refreshDocumentInfo();return docImportBefore(file)}const id=++documentReadId;readingFile=true;document.querySelector('#publish-error').textContent='';document.querySelector('#file-info').textContent='正在读取 '+file.name+'…';try{const doc=await extractDocument(file);if(id!==documentReadId||creationMode!=='image')return;uploadedDocument=doc;generatedSlice=null;fileAsset='';fileName=file.name;fileRevision++;refreshDocumentInfo();document.querySelector('#file-info').textContent='✓ 文档读取完成，点击「生成 Slice」';document.querySelector('#generation-status').textContent=doc.limitNote||'将从文档原文创建可提问的 Slice。';updatePublishPreview(true)}catch(err){if(id===documentReadId){document.querySelector('#publish-error').textContent=err.name==='PasswordException'?'PDF 已加密，请上传可直接读取的版本。':err.message;document.querySelector('#file-info').textContent=uploadedDocument?'仍使用：'+uploadedDocument.name:'文档读取失败'}}finally{if(id===documentReadId)readingFile=false}};
document.querySelector('#remove-document').onclick=()=>{documentReadId++;uploadedDocument=null;generatedSlice=null;readingFile=false;fileName='';fileAsset='';document.querySelector('#work-file').value='';document.querySelector('#file-info').textContent='';refreshDocumentInfo();updatePublishPreview(true)};
const docGenerateBefore=document.querySelector('#generate-slice').onclick;document.querySelector('#generate-slice').onclick=()=>{if(!uploadedDocument)return docGenerateBefore();if(readingFile)return;if(computeModel.value!=='local')return;const prompt=document.querySelector('#slice-prompt').value.trim();generatedSlice={html:documentSliceHtml(uploadedDocument),prompt,kind:document.querySelector('#generation-kind').value,image:fileAsset,documentText:uploadedDocument.text};publishForm.elements.title.value=(uploadedDocument.title+' · 问问这份文档').slice(0,50);publishForm.elements.description.value='直接向这份文档提问，查看相关原文和出处。';publishForm.elements.category.value='Knowledge';document.querySelector('#generation-status').textContent='已生成文档问答 Slice。可以在右侧提问、查看原文，然后发布。';document.querySelector('#publish-error').textContent='';updatePublishPreview(true)};
const docDataBefore=formData;formData=function(){const d=docDataBefore();return {...d,...(creationMode==='image'&&uploadedDocument?{sourceDocument:uploadedDocument}:{})}};
const docOpenBefore=openCreator;openCreator=function(work){docOpenBefore(work);const d=work||readStored(draftKey,null);uploadedDocument=d?.sourceDocument&&typeof d.sourceDocument.text==='string'?d.sourceDocument:null;if(uploadedDocument&&generatedSlice)generatedSlice.documentText=uploadedDocument.text;refreshDocumentInfo();if(creationMode==='image')setCreationMode('image',false)};
const docSubmitBefore=publishForm.onsubmit;publishForm.onsubmit=e=>{if(creationMode==='image'&&uploadedDocument&&generatedSlice?.documentText!==uploadedDocument.text){e.preventDefault();document.querySelector('#publish-error').textContent='文档已变更，请重新生成文档 Slice 后发布。';return}docSubmitBefore(e)};
const manualText=`Luma One 桌面灯产品说明书（虚构演示产品）

产品功能：Luma One 是一款桌面阅读灯，提供三档亮度和三种色温。灯头可上下调节，底座配有触控按钮。

亮度与色温：短按电源键开灯或关灯。开灯后短按亮度键，在低、中、高三档亮度之间循环。长按亮度键两秒切换暖光、自然光和冷光。

供电与无线使用：使用随附的 USB-C 线连接 5V / 2A 电源适配器。灯内没有电池，必须插电使用，不支持无线或充电后脱线使用。

定时功能：同时按住电源键和亮度键三秒，指示灯闪烁两次后开启 30 分钟自动关灯。再次操作可取消定时。

清洁与维护：关灯并拔下电源后，用柔软干布擦拭。请勿用水冲洗，不要使用酒精或研磨清洁剂。仅限室内干燥环境使用。

故障排查：灯不亮时先检查 USB-C 插头和电源适配器是否连接牢固，再尝试更换合规的 5V / 2A 电源。不应自行拆开底座。

保修政策：自购买之日起提供一年有限保修，需保留购买凭证。人为损坏、进水和擅自拆机不在保修范围内。

包装清单：桌面灯一台、USB-C 线一根、纸质快速指南一份。不附带电源适配器。

演示声明：以上产品、参数与保修政策均为虚构，仅用于展示文档转 Slice 的体验。`;
